# name: prior_intermediate_features_rate
# description: Rate of choosing intermediate-complexity objects on mumble trials where the display contains both extreme (empty and full) objects and intermediate objects.
def test_statistic(df):
    sub = df[df['query'] == 'prior']
    uniques = sub['objects'].drop_duplicates()
    lookup = {}
    for objs_str in uniques:
        objs = json.loads(objs_str)
        counts = [sum(o) for o in objs]
        min_c, max_c = min(counts), max(counts)
        if min_c == 0 and max_c > 1:
            inter = {i for i, c in enumerate(counts) if 0 < c < max_c}
            if inter:
                lookup[objs_str] = inter
    keys = sub['objects'].tolist()
    choices = sub['choice'].to_numpy()
    hits = [c in lookup[k] for c, k in zip(choices, keys) if k in lookup]
    return float(np.mean(hits)) if hits else 0.0

# name: foil_choice_rate_four_object_displays
# description: Rate of choosing any non-matching foil object in utterance trials with four-object displays.
def test_statistic(df):
    sub = df[df['query'] == 'utterance']
    uniques = sub[['objects', 'utterance']].drop_duplicates()
    lookup = {}
    for _, r in uniques.iterrows():
        objs = json.loads(r['objects'])
        if len(objs) == 4:
            utt = int(r['utterance'])
            non_matches = {i for i, o in enumerate(objs) if o[utt] == 0}
            if non_matches:
                lookup[(r['objects'], str(r['utterance']))] = non_matches
    keys = list(zip(sub['objects'], sub['utterance'].astype(str)))
    choices = sub['choice'].to_numpy()
    hits = [c in lookup[k] for c, k in zip(choices, keys) if k in lookup]
    return float(np.mean(hits)) if hits else 0.0

# name: intermediate_matching_competitor_rate
# description: Rate of choosing an intermediate-feature competitor in utterance trials where the heard word matches three or more objects with differing feature counts.
def test_statistic(df):
    sub = df[df['query'] == 'utterance']
    uniques = sub[['objects', 'utterance']].drop_duplicates()
    lookup = {}
    for _, r in uniques.iterrows():
        objs = json.loads(r['objects'])
        utt = int(r['utterance'])
        matches = [i for i, o in enumerate(objs) if o[utt] == 1]
        if len(matches) >= 3:
            counts = [sum(objs[i]) for i in matches]
            min_c, max_c = min(counts), max(counts)
            if min_c < max_c:
                inter = {matches[k] for k, c in enumerate(counts) if min_c < c < max_c}
                if inter:
                    lookup[(r['objects'], str(r['utterance']))] = inter
    keys = list(zip(sub['objects'], sub['utterance'].astype(str)))
    choices = sub['choice'].to_numpy()
    hits = [c in lookup[k] for c, k in zip(choices, keys) if k in lookup]
    return float(np.mean(hits)) if hits else 0.0
